type AppId = 'phone' | 'messages' | 'instagram' | 'echo' | 'gallery' | 'music' | 'studio' | 'diary' | 'notes' | 'quick' | 'voice' | 'calendar' | 'places' | 'browser' | 'contacts' | 'notifications' | 'files' | 'screentime' | 'secret';
type Detail = { kind: string; id: string } | null;

const cloneSeed = (): PhoneStore => JSON.parse(JSON.stringify(seedPhone)) as PhoneStore;
const usePhoneStore = () => {
  const [store, setStore] = useState<PhoneStore>(() => {
    try {
      const parsed = JSON.parse(localStorage.getItem('hyunjin-phone-store') ?? '');
      const seed = cloneSeed();
      const merged = { ...seed };
      for (const key in seed) {
        if (parsed[key] !== undefined) {
          (merged as any)[key] = parsed[key];
        }
      }
      return merged as PhoneStore;
    } catch { return cloneSeed(); }
  });
  const currentStore = useRef(store);
  currentStore.current = store;
  const publish = (items: ReviewProposal[]) => {
    // Use the same localStorage record as Edit Mode. Commit before updating the UI,
    // so storage failure cannot be mistaken for a successful approval.
    const next = publishActivity(currentStore.current, items);
    const serialized = JSON.stringify(next);
    localStorage.setItem('hyunjin-phone-store', serialized);
    if (localStorage.getItem('hyunjin-phone-store') !== serialized) {
      throw new Error('Phone storage did not confirm the saved activity.');
    }
    currentStore.current = next;
    setStore(next);
  };
  useEffect(() => {
    try {
      localStorage.setItem('hyunjin-phone-store', JSON.stringify(store));
    } catch {
      console.warn('Phone storage is full. Remove a large uploaded or generated image before adding more.');
    }
  }, [store]);
  return [store, setStore, publish] as const;
};

