function ApprovedExtras({ store, app, detail, setDetail }: { store: PhoneStore; app: AppId; detail: Detail; setDetail: (d: Detail) => void }) {
  if (app === 'instagram') {
    const story = detail?.kind === 'approved-story' ? store.instagramStories.find(s => s.id === detail.id) : undefined;
    return story ? <div className="mb-5 rounded-3xl border border-white/10 bg-white/5 p-5">
      <button onClick={() => setDetail(null)} className="mb-4 text-xs text-[#e7aabb]">← stories</button>
      <p className="text-sm font-medium">{story.user} · {story.time}</p>
      {story.dataUrl && <img src={story.dataUrl} alt="" className="mt-3 w-full rounded-2xl" />}
      <p className="mt-4 text-sm">{story.caption}</p>
    </div> : store.instagramStories.length ? <div className="mb-5">
      <SectionTitle>new stories</SectionTitle><div className="flex gap-3 overflow-x-auto pb-2">
        {store.instagramStories.map(s => <button key={s.id} onClick={() => setDetail({ kind: 'approved-story', id: s.id })} className="min-w-20 rounded-2xl border border-[#d98ca7]/40 bg-white/5 p-3 text-left text-xs"><span className="block truncate">{s.user}</span><span className="mt-1 block text-[10px] text-white/40">{s.time}</span></button>)}
      </div>
    </div> : null;
  }
  if (app === 'gallery' && detail?.kind === 'album') {
    const photos = store.gallery.filter(g => detail.id === 'Favorites' ? g.favorite : g.album === detail.id);
    return <div className="mb-6"><button onClick={() => setDetail(null)} className="text-xs text-[#e7aabb]">← gallery</button><h3 className="mt-3 font-serif text-2xl">{detail.id}</h3><div className="mt-3 grid grid-cols-3 gap-2">{photos.map(g => <button key={g.id} onClick={() => setDetail({ kind: 'gallery', id: g.id })}><GalleryVisual item={g} /></button>)}</div></div>;
  }
  if (app === 'music' && store.musicActivity.length) return <div className="mb-5">
    <SectionTitle>recent listening</SectionTitle>
    {store.musicActivity.map(a => <div key={a.id} className="mb-2 rounded-2xl border border-white/10 bg-white/5 p-3"><p className="text-sm">{a.title}</p><p className="mt-1 text-xs text-white/55">{a.content} · {a.time}</p></div>)}
  </div>;
  return null;
}

